const A = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";

export function b58encode(buf) {
  let origlen = buf.length;
  let i = 0;
  while (i < buf.length && buf[i] === 0) i++;
  const stripped = buf.subarray(i);
  let acc = 0n;
  for (const b of stripped) acc = acc * 256n + BigInt(b);
  let s = "";
  while (acc > 0n) { const r = acc % 58n; acc = acc / 58n; s = A[Number(r)] + s; }
  return A[0].repeat(origlen - stripped.length) + s;
}

export function b58decode(str) {
  let v = str.replace(/[ \t\n\r\v\f]+$/, "");   // python str.rstrip() (ASCII ws subset)
  const origlen = v.length;
  const v2 = v.replace(/^1+/, "");
  const newlen = v2.length;
  let acc = 0n;
  for (const ch of v2) {
    const idx = A.indexOf(ch);
    if (idx < 0) throw new Error(`Invalid character '${ch}'`);
    acc = acc * 58n + BigInt(idx);
  }
  const bitlen = acc === 0n ? 0 : acc.toString(2).length;
  const nbytes = origlen - newlen + ((bitlen + 7) >> 3);
  const out = Buffer.alloc(nbytes);
  let a = acc;
  for (let k = nbytes - 1; k >= 0; k--) { out[k] = Number(a & 255n); a >>= 8n; }
  return out;
}

// python repr(bytes)
export function pyrepr(buf) {
  let hasS = false, hasD = false;
  for (const b of buf) { if (b === 39) hasS = true; if (b === 34) hasD = true; }
  const q = (hasS && !hasD) ? '"' : "'";
  let s = "b" + q;
  for (const b of buf) {
    if (b === 92) s += "\\\\";
    else if (b === 9) s += "\\t";
    else if (b === 10) s += "\\n";
    else if (b === 13) s += "\\r";
    else if (String.fromCharCode(b) === q) s += "\\" + q;
    else if (b >= 0x20 && b < 0x7f) s += String.fromCharCode(b);
    else s += "\\x" + b.toString(16).padStart(2, "0");
  }
  return s + q;
}
